add_filter( 'the_excerpt_rss', 'perfectpixel_featured_image_in_feed' );
add_filter( 'the_content_feed', 'perfectpixel_featured_image_in_feed' );

function perfectpixel_featured_image_in_feed( $content ) {
	$post = get_post();
	if ( ! $post || ! has_post_thumbnail( $post ) ) {
		return $content;
	}
	$size  = sanitize_key( '{{feed_image_size}}' );
	$image = get_the_post_thumbnail( $post, $size ? $size : 'medium_large', array( 'style' => 'display:block;max-width:100%;height:auto;margin-bottom:1em' ) );
	return '<p>' . $image . '</p>' . $content;
}
